import { chromium, expect } from '@playwright/test';
import { mkdir, writeFile } from 'node:fs/promises';
const output = '../target/verification/alias-search/imported-live';
await mkdir(output, { recursive: true });
const browser = await chromium.launch();
const context = await browser.newContext({ viewport: { width: 1200, height: 900 } });
await context.tracing.start({ screenshots: true, snapshots: true, sources: true });
const page = await context.newPage();
try {
  const responsePromise = page.waitForResponse(r => r.url().includes('/api/search?') && new URL(r.url()).searchParams.get('term') === 'west mid');
  await page.goto('http://127.0.0.1:5184/?q=west%20mid&strictness=0.6');
  const response = await responsePromise;
  expect(response.ok()).toBe(true);
  const body = await response.json();
  const unite = body.entities.find(e => e.name === 'Unite the Union');
  expect(unite.match_source.kind).toBe('alias');
  expect(unite.match_source.name).toContain('West Midlands');
  await expect(page.locator('.entity-name')).toHaveText(body.entities.map(e => e.name));
  const row = page.locator('.entity-row').filter({ has: page.getByRole('link', { name: 'Unite the Union', exact: true }) });
  await expect(row.locator('.entity-alias')).toHaveText('Matched alias: ' + unite.match_source.name);
  await expect(row.locator('.entity-name')).toHaveAccessibleDescription('Matched alias: ' + unite.match_source.name);
  await expect(row.locator('.entity-name')).toHaveAttribute('href', '/funders/' + unite.id + '?q=west+mid&strictness=0.6');
  const direct = body.entities.find(e => e.name === 'UNISON West Midlands');
  expect(direct.match_source.kind).toBe('name');
  const directRow = page.locator('.entity-row').filter({ has: page.getByRole('link', { name: direct.name, exact: true }) });
  await expect(directRow.locator('.entity-alias')).toHaveCount(0);
  await page.screenshot({ path: output + '/desktop.png', fullPage: true });
  await writeFile(output + '/response.json', JSON.stringify(body, null, 2));
  await writeFile(output + '/desktop.aria.txt', await page.locator('body').ariaSnapshot());
  await page.setViewportSize({ width: 360, height: 780 });
  await expect(row.locator('.entity-alias')).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
  await page.screenshot({ path: output + '/mobile.png', fullPage: true });
  const canonicalPromise = page.waitForResponse(r => r.url().includes('/api/search?') && new URL(r.url()).searchParams.get('term') === 'Unite the Union');
  await page.getByRole('searchbox').fill('Unite the Union');
  const canonicalBody = await (await canonicalPromise).json();
  const canonical = canonicalBody.entities.find(e => e.id === unite.id);
  expect(canonical.match_source.kind).toBe('name');
  const canonicalRow = page.locator('.entity-row').filter({ has: page.getByRole('link', { name: 'Unite the Union', exact: true }) });
  await expect(canonicalRow.locator('.entity-alias')).toHaveCount(0);
  await canonicalRow.locator('.entity-name').click();
  await expect(page).toHaveURL(new RegExp('/funders/' + unite.id));
  await expect(page.getByRole('heading', { name: 'Unite the Union', exact: true })).toBeVisible();
  await page.screenshot({ path: output + '/canonical-details.png', fullPage: true });
  await writeFile(output + '/proof.json', JSON.stringify({ source: 'copy of imported database', alias: unite, canonical, directName: direct, mobileOverflow: false, canonicalDetailsOpened: true }, null, 2));
  console.log('Imported west mid: alias explained; direct name unlabelled; canonical identity preserved; mobile fits; canonical details opened.');
} finally {
  await context.tracing.stop({ path: output + '/trace.zip' });
